1	/**
2	 * ending-calls.ts — what a run's closing message calls, and whether that is allowed.
3	 *
4	 * # The rule
5	 *
6	 * People and agents are the same kind of thing here: whoever a run hands the work
7	 * to holds the ball next, and exactly one of them does. A closing message therefore
8	 * ends by calling **at most one** thing —
9	 *
10	 *   - one agent, as a line holding nothing but `/name`;
11	 *   - one person, as a single `@login` mention of somebody who can act;
12	 *   - or nobody at all, in which case the machinery tells the person this work
13	 *     belongs to.
14	 *
15	 * Two calls is not "a hand-off plus a notification": it is two people who both
16	 * believe they were asked, and work that happens twice or not at all. The prompt
17	 * states the rule; this is the part that can see whether it was kept.
18	 *
19	 * # Why a count of invocations and not a reading of intent
20	 *
21	 * A directive line and an `@login` in prose are exactly the two ways a run can make
22	 * something happen to another participant, and both are already read by the
23	 * machinery for other purposes (`extract_directive.ts` dispatches on the first,
24	 * `post_result_comment.ts` notifies on the second). Counting what those two readers
25	 * recognise keeps the check honest: a line that neither would act on is not a call,
26	 * and telling an agent it made a call that dispatched nothing would be a lie.
27	 *
28	 * Pure: the caller supplies what counts as a callable agent and a callable person.
29	 */
30	import { AGENT_NAME_PATTERN } from "./agent-name.ts";
31	import { lineForms } from "./comment-command.ts";
32	import { mentionsIn } from "./mention.ts";
33	
34	const DIRECTIVE = new RegExp(`^\\/(${AGENT_NAME_PATTERN})$`);
35	
36	export interface EndingCalls {
37	  /** Agents called, in the order they were named, without repeats. */
38	  agents: string[];
39	  /** People called, by the login as written, without repeats. */
40	  humans: string[];
41	}
42	
43	export interface CallableSet {
44	  /** Whether a definition exists for this name, which is what makes a line dispatch. */
45	  knowsAgent: (name: string) => boolean;
46	  /** Logins that are somebody this run may call: a participant, or the work's owner. */
47	  humans: Iterable<string>;
48	}
49	
50	/**
51	 * Everything the closing message calls, in prose order, agent lines first.
52	 *
53	 * Agent lines are read the way `extract_directive.ts` reads them — the same
54	 * `lineForms` tolerance for a markdown-backticked `/name`, and the same requirement
55	 * that a definition exists — so a count here and a dispatch there cannot disagree
56	 * about what a line is.
57	 */
58	export function endingCalls(output: string, callable: CallableSet): EndingCalls {
59	  const agents: string[] = [];
60	  for (const rawLine of output.split("\n")) {
61	    for (const candidate of lineForms(rawLine)) {
62	      const match = DIRECTIVE.exec(candidate);
63	      if (!match) continue;
64	      const agent = match[1]!;
65	      if (!callable.knowsAgent(agent)) continue;
66	      if (!agents.includes(agent)) agents.push(agent);
67	    }
68	  }
69	
70	  return { agents, humans: calledHumans(output, callable.humans) };
71	}
72	
73	/**
74	 * The people the text calls, by login, without repeats.
75	 *
76	 * A mention is a call only when its login is one of `humans`. An unknown `@name` is
77	 * not a call: `domain/work/mention.ts` escapes it before the comment is posted, so
78	 * nobody is reached by it, and counting it would reject a message that reaches no one
79	 * twice.
80	 *
81	 * Exported for the result comment, which asks the same question of the text it is
82	 * about to post — it has already read the participants on its own token, and it must
83	 * not decide "was this a call" a second, differently-spelled way.
84	 */
85	export function calledHumans(text: string, humans: Iterable<string>): string[] {
86	  const allowed = new Set([...humans].map((login) => login.trim().toLowerCase()).filter(Boolean));
87	  const called: string[] = [];
88	  for (const login of mentionsIn(text)) {
89	    if (!allowed.has(login.toLowerCase())) continue;
90	    if (called.some((seen) => seen.toLowerCase() === login.toLowerCase())) continue;
91	    called.push(login);
92	  }
93	  return called;
94	}
95	
96	/** How many things this message calls. */
97	function callCount(calls: EndingCalls): number {
98	  return calls.agents.length + calls.humans.length;
99	}
100	
101	/** The calls, as the reader would write them: `` `/engineer`, `@alice` ``. */
102	function namedCalls(calls: EndingCalls): string {
103	  return [
104	    ...calls.agents.map((agent) => `\`/${agent}\``),
105	    ...calls.humans.map((login) => `\`@${login}\``),
106	  ].join(", ");
107	}
108	
109	/**
110	 * The sentence naming what is wrong with the message, or `undefined` when it is fine.
111	 *
112	 * Written for the agent as much as for the log: it is what the run is handed when it
113	 * is asked to write the message again, and naming the calls it did make is the only
114	 * way it can see which of them to keep.
115	 */
116	export function endingCallProblem(calls: EndingCalls): string | undefined {
117	  const count = callCount(calls);
118	  if (count <= 1) return undefined;
119	  return `it calls ${count} things: ${namedCalls(calls)}`;
120	}

